## Code Example

```javascript
// Minimal snippet demonstrating schema selection and query
async function getTenantUsers(tenantId) {
  const schema = validateTenantSchema(tenantId);
  const cacheKey = `users:${tenantId}`;

  // Check Redis cache first
  const cached = await redis.get(cacheKey);
  if (cached) return JSON.parse(cached);

  // Execute parameterized query with dynamic schema
  const query = `SELECT Id, Username, Email FROM [${schema}].Users WHERE IsActive = 1`;
  const results = await sql.query(query);

  // Cache results for 5 minutes
  await redis.setex(cacheKey, 300, JSON.stringify(results));
  return results;
}
```

